-- Two more ready-made quality sets beside Good everyday, so a title's Quality
-- control offers Save space, Good everyday and Best. Must match domain.SaveSpace()
-- and domain.Best(); a test checks it. A set someone already named this is kept.
INSERT INTO pick_rules (created_at, created_by, updated_at, updated_by, name, kinds, revision, preset, body)
SELECT strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), '{"kind":"system"}', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), '{"kind":"system"}',
       'Save space', '["movie","show"]', 1, 1,
       '{"steps":[{"quality":"cam","allowed":false},{"quality":"telesync","allowed":false},{"quality":"sd_tv","allowed":false},{"quality":"sd_dvd","allowed":false},{"quality":"720p_tv","allowed":true},{"quality":"720p_web","allowed":true},{"quality":"720p_bluray","allowed":true},{"quality":"1080p_tv","allowed":true},{"quality":"1080p_web","allowed":true},{"quality":"1080p_bluray","allowed":false},{"quality":"1080p_remux","allowed":false},{"quality":"2160p_web","allowed":false},{"quality":"2160p_bluray","allowed":false},{"quality":"2160p_remux","allowed":false}],"good_enough_at":"1080p_web","traits":[{"trait":"hevc","points":20},{"trait":"web_dl","points":5},{"trait":"upscaled","points":-50},{"trait":"dubbed_only","points":-30}],"must_have":[],"never":["sample","executable","password_protected","disc_image","hardcoded_subs","3d","cam","telesync"],"min_points":0,"size_limits":{"*":{"min":7158278,"max":44739242,"per_minute":true}},"protocol":{"prefer":"either","wait_minutes_torrent":0,"wait_minutes_usenet":0,"skip_wait_at_good_enough":false},"language":{"wanted":[],"original_ok":true},"order":"quality_then_points","upgrade_min_points":10,"proper_policy":{"mode":"take_any"}}'
WHERE NOT EXISTS (SELECT 1 FROM pick_rules WHERE name = 'Save space');

INSERT INTO pick_rules (created_at, created_by, updated_at, updated_by, name, kinds, revision, preset, body)
SELECT strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), '{"kind":"system"}', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), '{"kind":"system"}',
